/* =============================================================================
   INV-03 · Resultado de la Importación — estilos.

   Transcritos del HTML aprobado de la pantalla. NINGÚN color literal: todo sale de
   los tokens de `tokens.css`. Los tamaños de eyebrow (11px), título (24px), subtítulo
   (14px), etiqueta de cifra (10px) y valor de cifra (22px) son los del HTML aprobado
   (F-209), no los tokens `--bw-size-*`; el resto de tamaños también son los suyos.

   Nota de tokens: el sistema no define un blanco puro y las tarjetas y tablas del
   HTML son `#fff` sobre el fondo `--bw-cold-white` del shell. Se usa el neutro claro
   más próximo, `--bw-warm-cream` (#FAF8F4), más claro que el fondo de contenido; las
   cabeceras de tabla siguen con `--bw-surface-mist`.
   ========================================================================== */

/* La raíz de la pantalla es hija directa de `.bwcnt` (overflow: hidden): sin su
   propio scroll, con la ventana baja se recortaría sin barra (F-186/F-189/F-190). */
.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 40px 48px 56px;
}

.inner {
  width: 100%;
  max-width: 860px;
  margin: 0 auto;
}

/* ── Cabecera ────────────────────────────────────────────────────────────── */

.hdr {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 28px;
}

.icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.iconOk {
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
}

.iconWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning-dark);
}

.iconFail {
  background: var(--bw-tint-danger);
  color: var(--bw-error-text);
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-brass);
  margin-bottom: 6px;
}

.title {
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: 24px;
  letter-spacing: 0.3px;
  line-height: 1.2;
  margin: 0 0 4px;
}

.titleOk {
  color: var(--bw-success-dark);
}

.titleWarn {
  color: var(--bw-warning-dark);
}

.titleFail {
  color: var(--bw-error-text);
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.5;
  margin: 0;
}

/* ── Cifras ──────────────────────────────────────────────────────────────── */

.statsRow {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin-bottom: 24px;
}

.statCard {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 6px;
  padding: 14px 16px;
}

.statLabel {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--bw-steel-mist);
  margin-bottom: 5px;
}

.statValue {
  font-family: var(--bw-font-mono);
  font-weight: 700;
  font-size: 22px;
  line-height: 1;
  color: var(--bw-deep-steel);
}

.statValue[data-tone='ok'] {
  color: var(--bw-success-dark);
}

.statValue[data-tone='warn'] {
  color: var(--bw-warning);
}

.statValue[data-tone='err'] {
  color: var(--bw-danger);
}

/* El tiempo es una medida, no un recuento: 18 px y algo de aire arriba, como en el
   HTML aprobado. Va después de `.statValue` para poder ganarle el tamaño. */
.statValueTime {
  font-size: 18px;
  padding-top: 3px;
}

.statSub {
  font-size: 11px;
  color: var(--bw-input-placeholder);
  margin-top: 3px;
}

/* ── Bloque de fallo total ───────────────────────────────────────────────── */

.failBlock {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  padding: 18px 20px;
  margin-bottom: 20px;
}

.failTitle {
  font-size: 14px;
  font-weight: 600;
  color: var(--bw-error-text);
  margin-bottom: 4px;
}

.failDesc {
  font-size: 13px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
}

/* ── Títulos de sección ──────────────────────────────────────────────────── */

.secTitle {
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--bw-steel-mist);
  margin: 0 0 8px;
}

.secHint {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  font-style: italic;
  margin: 0 0 10px;
}

/* ── Tablas ──────────────────────────────────────────────────────────────── */

.tblCard {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 20px;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.table th {
  background: var(--bw-surface-mist);
  padding: 9px 14px;
  text-align: left;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--bw-steel-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.table td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--bw-divider-mist);
  color: var(--bw-ink-steel);
  vertical-align: middle;
}

.table tbody tr:last-child td {
  border-bottom: none;
}

.refCode {
  font-family: var(--bw-font-mono);
  font-weight: 500;
  font-size: 12px;
  color: var(--bw-deep-steel);
}

.badge {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
}

.badgeBrand {
  background: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover);
}

.badgeIso {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-ink-steel-soft);
  border: 1px solid var(--bw-badge-neutral-border-soft);
}

.badgePub {
  background: var(--bw-badge-success-bg);
  color: var(--bw-success-dark);
  border: 1px solid var(--bw-badge-success-border);
}

/* ── Panel de errores ────────────────────────────────────────────────────── */

.errPanel {
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 20px;
}

.errHdr {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 13px 16px;
  background: none;
  border: none;
  cursor: pointer;
  user-select: none;
  text-align: left;
  font-family: var(--bw-font-body);
  transition: background 0.12s;
}

.errHdr:hover {
  background: var(--bw-danger-hover-bg);
}

.errIcon {
  color: var(--bw-danger);
  flex-shrink: 0;
}

.errLbl {
  flex: 1;
  font-size: 13px;
  font-weight: 500;
  color: var(--bw-error-text);
}

.errChev {
  color: var(--bw-input-placeholder);
  transition: transform 0.2s;
}

.errChevOpen {
  transform: rotate(90deg);
}

.errBody {
  border-top: 1px solid var(--bw-badge-danger-border);
}

.cellMonoMuted {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.cellMono {
  font-family: var(--bw-font-mono);
  font-size: 12px;
}

.cellErr {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  color: var(--bw-error-text);
}

.errType {
  font-family: var(--bw-font-mono);
  font-size: 11px;
  color: var(--bw-error-text);
  background: var(--bw-danger-hover-bg);
  border: 1px solid var(--bw-badge-danger-border);
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
}

.moreCell {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  font-style: italic;
  text-align: center;
  color: var(--bw-input-placeholder);
}

.dlRow {
  padding: 12px 16px;
  border-top: 1px solid var(--bw-divider-mist);
  display: flex;
  justify-content: flex-end;
}

.btnDl {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 13px;
  font-weight: 500;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: border-color 0.12s, color 0.12s;
}

.btnDl:hover {
  border-color: var(--bw-brass);
  color: var(--bw-warning-dark);
}

/* ── Salidas ─────────────────────────────────────────────────────────────── */

.btnRow {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btnPrimary {
  padding: 11px 22px;
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  border: none;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.15s;
}

.btnPrimary:hover {
  opacity: 0.9;
}

.btnText {
  padding: 11px 12px;
  background: none;
  border: none;
  font-family: var(--bw-font-body);
  font-size: 14px;
  color: var(--bw-steel-mist);
  cursor: pointer;
  transition: color 0.12s;
}

.btnText:hover {
  color: var(--bw-ink-steel);
}
